import{c as s,Q as a,j as o,m as e}from"./chunks/framework.DOi4mjdC.js";const r="/assets/%E5%9C%BA%E6%99%AF1%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.DyRSU9It.png",p="/assets/%E5%9C%BA%E6%99%AF2%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.DMeolnuK.png",n="/assets/%E5%9C%BA%E6%99%AF3%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.DZBR8UZ3.png",i="/assets/%E5%9C%BA%E6%99%AF4%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.C6SlwhCL.png",l="/assets/%E5%9C%BA%E6%99%AF5%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.CyNv-i_c.png",N="/assets/%E5%9C%BA%E6%99%AF6%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.EJaJUTVP.png",E="/assets/%E5%9C%BA%E6%99%AF7%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.BXRYXf78.png",d="/assets/%E5%9C%BA%E6%99%AF13%E4%B8%89%E7%BB%B4Tensor%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.nX2qXOmB.png",B="/assets/%E5%9C%BA%E6%99%AF14%E4%B8%89%E7%BB%B4Tensor%E7%9A%84%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.sJmyGjZo.png",g="/assets/%E5%9C%BA%E6%99%AF15%E4%B8%89%E7%BB%B4Tensor%E7%9A%84%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E5%8F%98%E6%8D%A2.BA1NHX8N.png",T="/assets/%E5%9C%BA%E6%99%AF16%E4%BD%BF%E7%94%A8%E4%BA%A4%E7%BB%87%E6%8C%87%E4%BB%A4%E7%9A%84ND2NZ%E8%BD%AC%E7%BD%AE.C7mVsDxm.png",_="/assets/%E5%9C%BA%E6%99%AF1-NZ2ND-1-2%E8%BD%B4%E4%BA%92%E6%8D%A2.qpCHeldD.png",D="/assets/%E5%9C%BA%E6%99%AF2-NZ2NZ-1-2%E8%BD%B4%E4%BA%92%E6%8D%A2.CI2VRTrx.png",c="/assets/%E5%9C%BA%E6%99%AF3-NZ2NZ-%E5%B0%BE%E8%BD%B4%E5%88%87%E5%88%86.Dv_oSMCo.png",m="/assets/%E5%9C%BA%E6%99%AF4-NZ2ND-%E5%B0%BE%E8%BD%B4%E5%88%87%E5%88%86.D9mXfD7S.png",A="/assets/%E5%9C%BA%E6%99%AF5-NZ2ND-%E5%B0%BE%E8%BD%B4%E5%90%88%E5%B9%B6.eShaa3O0.png",h="/assets/%E5%9C%BA%E6%99%AF6-NZ2NZ-%E5%B0%BE%E8%BD%B4%E5%90%88%E5%B9%B6.TrnAGw9X.png",u="/assets/%E5%9C%BA%E6%99%AF7-%E4%BA%8C%E7%BB%B4%E8%BD%AC%E7%BD%AE.HKQQVCfR.png",S="/assets/%E5%9C%BA%E6%99%AF13-%E4%BA%8C%E7%BB%B4%E8%BD%AC%E7%BD%AE%E6%88%96%E8%80%85%E4%B8%89%E7%BB%B4%E7%9A%84%E5%90%8E%E4%B8%A4%E7%BB%B4%E8%BD%AC%E7%BD%AE.CIdAQuOx.png",H="/assets/%E5%9C%BA%E6%99%AF16-%E4%BD%BF%E7%94%A8%E4%BA%A4%E7%BB%87%E6%8C%87%E4%BB%A4%E8%BF%9B%E8%A1%8C%E4%B8%A4%E7%BB%B4ND2NZ%E8%BD%AC%E7%BD%AE.tbvmlXrn.png",y=JSON.parse('{"title":"Transpose","description":"","frontmatter":{},"headers":[{"level":1,"title":"Transpose","slug":"transpose"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/张量变换/Transpose-96.md","filePath":"api/SIMD-API/高阶API/张量变换/Transpose-96.md"}'),Z={name:"api/SIMD-API/高阶API/张量变换/Transpose-96.md"};function q(C,t,f,b,P,v){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="transpose" tabindex="-1">Transpose <a class="header-anchor" href="#transpose" aria-label="Permalink to &quot;Transpose&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>对输入数据进行数据排布及Reshape操作，具体功能如下：</p><p>【场景1：NZ2ND，1、2轴互换】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, N, H/N], origin_shape:[B, S, N, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 1</strong> 场景1数据排布变换<br><img src="'+r+'" alt="" title="场景1数据排布变换"></p><p>【场景2：NZ2NZ，1、2轴互换】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, H/N/16, N/16, 16, 16], origin_shape:[B, S, N, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 2</strong> 场景2数据排布变换<br><img src="'+p+'" alt="" title="场景2数据排布变换"></p><p>【场景3：NZ2NZ，尾轴切分】</p><p>输入Tensor { shape:[B, H / 16, S / 16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, N, H/N/16, S / 16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 3</strong> 场景3数据排布变换<br><img src="'+n+'" alt="" title="场景3数据排布变换"></p><p>【场景4：NZ2ND，尾轴切分】</p><p>输入Tensor { shape:[B, H / 16, S / 16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, N, S, H/N], origin_shape:[B, N, S, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 4</strong> 场景4数据排布变换<br><img src="'+i+'" alt="" title="场景4数据排布变换"></p><p>【场景5：NZ2ND，尾轴合并】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, H], origin_shape:[B, S, H], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 5</strong> 场景5数据排布变换<br><img src="'+l+'" alt="" title="场景5数据排布变换"></p><p>【场景6：NZ2NZ，尾轴合并】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, H/16, S/16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图 6</strong> 场景6数据排布变换<br><img src="'+N+'" alt="" title="场景6数据排布变换"></p><p>【场景7：二维转置】</p><p>支持在UB上对二维Tensor进行转置，其中srcShape中的H、W均是16的整倍。</p><p><strong>图 7</strong> 场景7数据排布变换<br><img src="'+E+'" alt="" title="场景7数据排布变换"></p><p>【场景13：二维转置或者三维的后两维转置】</p><p>支持在UB上对二维Tensor进行转置或者对三维Tensor的最后两维进行转置，二维Tensor转置同场景7的数据排布变换。</p><p><strong>图 8</strong> 场景13三维Tensor数据排布变换<br><img src="'+d+'" alt="" title="场景13三维Tensor数据排布变换"></p><p>【场景14：三维中的第一维和第二维互换】</p><p>支持在UB上对三维Tensor中的第一维和第二维互换。</p><p><strong>图 9</strong> 场景14三维Tensor的数据排布变换<br><img src="'+B+'" alt="" title="场景14三维Tensor的数据排布变换"></p><p>【场景15：三维中的第一维和第三维互换】</p><p>支持在UB上对三维Tensor中的第一维和第三维互换。</p><p><strong>图 10</strong> 场景15三维Tensor的数据排布变换<br><img src="'+g+'" alt="" title="场景15三维Tensor的数据排布变换"></p><p>【场景16：使用交织指令进行两维ND2NZ转置】</p><p>支持在UB上使用<a href="./../../基础API/Memory矢量计算/数据重排（ISASI）/Interleave.html">交织指令</a>对二维ND Tensor转置为NZ。</p><p><strong>图 11</strong> 场景16使用交织指令的ND2NZ转置<br><img src="'+T+'" alt="" title="场景16使用交织指令的ND2NZ转置"></p><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>对应Transpose的11种功能场景，每种功能场景的算法框图如图所示。</p><p><strong>图 12</strong> 场景1：NZ2ND，1、2轴互换<br><img src="'+_+'" alt="" title="场景1-NZ2ND-1-2轴互换"></p><p>计算过程分为如下几步：</p><p>先后沿H/N方向，N方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：沿S方向转置S/16个连续的16*16的方形到temp中，在temp中每个方形与方形之间连续存储；</li><li>第2次TransDataTo5HD步骤：将temp中S/16个16*16的方形转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N)*N个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移16个元素。</li></ol><p><strong>图 13</strong> 场景2：NZ2NZ，1、2轴互换<br><img src="'+D+'" alt="" title="场景2-NZ2NZ-1-2轴互换"></p><p>计算过程分为如下几步：</p><p>先后沿H/N方向，N方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：沿S方向分别取S/16个连续的16*16的方形到temp中，在temp中每个方形与方形之间连续存储；</li><li>第2次TransDataTo5HD步骤：将temp中S/16个16*16的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N)*N个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移N*16个元素。</li></ol><p><strong>图 14</strong> 场景3：NZ2NZ，尾轴切分<br><img src="'+c+'" alt="" title="场景3-NZ2NZ-尾轴切分"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置S/16个连续的16*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到temp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移S*16个元素。</li></ol><p><strong>图 15</strong> 场景4：NZ2ND，尾轴切分<br><img src="'+m+'" alt="" title="场景4-NZ2ND-尾轴切分"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置S/16个连续的16*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的数据转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N+16-1)/16*16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移(H/N+16-1)/16*16*S个元素。</li></ol><p><strong>图 16</strong> 场景5：NZ2ND，尾轴合并<br><img src="'+A+'" alt="" title="场景5-NZ2ND-尾轴合并"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置一个S*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H+16-1)/16*16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移H/N*S个元素。</li></ol><p><strong>图 17</strong> 场景6：NZ2NZ，尾轴合并<br><img src="'+h+'" alt="" title="场景6-NZ2NZ-尾轴合并"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置一个S*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移S*16个元素。</li></ol><p><strong>图 18</strong> 场景7：二维转置<br><img src="'+u+'" alt="" title="场景7-二维转置"></p><p>计算过程如下：</p><ol><li>调用TransDataTo5HD，通过设置不同的源操作数地址序列和目的操作数地址序列，将[H, W]转置为[W, H]，src和dst均是ND格式。</li></ol><p><strong>图 19</strong> 场景13 : 二维转置或者三维的后两维转置<br><img src="'+S+'" alt="" title="场景13-二维转置或者三维的后两维转置"></p><p>计算过程如下：</p><ol><li>调用内部计算逻辑，通过设置不同的源操作数地址序列，连续写入目的操作数地址中，将[H, W]转置为[W, H]，或者将[N, H, W]转置为[N, W, H]，src和dst均是ND格式。</li></ol><p>场景14、场景15的转换过程和上述场景13中三维转置的转换过程基本一致，只是指定转置的维度不同。</p><p><strong>图 20</strong> 场景16 ：使用交织指令进行两维ND2NZ转置<br><img src="'+H+`" alt="" title="场景16-使用交织指令进行两维ND2NZ转置"></p><p>计算过程如下：</p><ol><li>调用内部计算逻辑，通过设置不同的源操作数地址序列，连续写入目的操作数地址中，将[H, W] ND格式转置为[W1,H1,H0,W0] NZ格式，H = H1 * H0，W = W1 * W0，H0=16，W0=2，src是ND格式，dst是NZ格式。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间大小BufferSize的获取方法：通过<a href="./Transpose-Tiling.html">Transpose Tiling</a>中提供的<strong>GetTransposeMaxMinTmpSize</strong>接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><p>临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式，因此Transpose接口的函数原型有两种：</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Transpose(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;uint8_t&gt; &amp;sharedTmpBuffer, TransposeType transposeType, ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><p>该方式下开发者需自行申请并管理临时内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Transpose(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, TransposeType transposeType, ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><p>该方式下开发者无需申请，但是需要预留临时空间的大小。</p></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。 场景1到场景7支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float；场景13到场景15支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float；场景16支持的数据类型为：int8_t、uint8_t。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>共享缓冲区，用于存放API内部计算产生的临时数据。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。共享缓冲区大小的获取方式请参考Transpose Tiling。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>transposeType</td><td>输入</td><td>数据排布及reshape的类型，类型为TransposeType枚举类。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen570192952518&quot;&gt;enum class TransposeType : uint8_t { TRANSPOSE_TYPE_NONE, // default value TRANSPOSE_NZ2ND_0213, // 场景1：NZ2ND，1、2轴互换 TRANSPOSE_NZ2NZ_0213, // 场景2：NZ2NZ，1、2轴互换 TRANSPOSE_NZ2NZ_012_WITH_N, // 场景3：NZ2NZ，尾轴切分 TRANSPOSE_NZ2ND_012_WITH_N, // 场景4：NZ2ND，尾轴切分 TRANSPOSE_NZ2ND_012_WITHOUT_N, // 场景5：NZ2ND，尾轴合并 TRANSPOSE_NZ2NZ_012_WITHOUT_N, // 场景6：NZ2NZ，尾轴合并 TRANSPOSE_ND2ND_ONLY, // 场景7：二维转置 TRANSPOSE_ND_UB_GM, // 当前不支持 TRANSPOSE_GRAD_ND_UB_GM, // 当前不支持 TRANSPOSE_ND2ND_B16, // 当前不支持 TRANSPOSE_NCHW2NHWC, // 当前不支持 TRANSPOSE_NHWC2NCHW, // 当前不支持 TRANSPOSE_ND2ND_021, // 场景13：二维转置或者三维中后两维转置 TRANSPOSE_ND2ND_102, // 场景14：三维中第一维和第二维互换 TRANSPOSE_ND2ND_210, // 场景15：三维中第一维和第三维互换 TRANSPOSE_ND2NZ_WITH_INTLV // 场景16：使用交织指令进行两维ND2NZ转置 };&lt;/pre&gt;</td></tr><tr><td>tiling</td><td>输入</td><td>计算所需tiling信息，Tiling信息的获取请参考Transpose Tiling。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>场景13到场景16仅在Ascend 950PR/Ascend 950DT上支持。</li><li>Ascend 950PR/Ascend 950DT，场景13到场景16不支持dst和src空间复用。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例为场景1（NZ2ND，1、2轴互换）示例：</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape：[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, N, H/N], origin_shape:[B, S, N, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p>B=1，N=2, S=64, H/N=32，输入数据类型均为half。更多完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_libraries/08_tensor_transformation/transpose" target="_blank" rel="noreferrer">Transpose样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dst：输入Tensor</span></span>
<span class="line"><span>// src：输出Tensor</span></span>
<span class="line"><span>// NZ2ND，1、2轴互换</span></span>
<span class="line"><span>AscendC::Transpose(dst, src, AscendC::TransposeType::TRANSPOSE_NZ2ND_0213, this-&gt;tiling);</span></span></code></pre></div>`,99)])])}const I=s(Z,[["render",q]]);export{y as __pageData,I as default};
